/**
 * Assembles a request path from URL fragments and environment origin data.
 */
export class PathAssembler {
  constructor() {
    this.pathSeparator = '/';
    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    this.schemeRelativePattern = /^([a-z][a-z\d+\-.]*:)?\/\//i;
  }

  buildFullPath(request, protocol, joinContext, origin) {
    const requestedURL = request.requestedURL;
    const baseURL = request.baseURL;
    const source = protocol.raw != null ? protocol.raw : requestedURL;
    const isAbsolute = this.schemeRelativePattern.test(source) &&
      this.schemeRelativePattern.test(origin.href);

    if (baseURL && !isAbsolute) {
      return joinContext.relativeURL
        ? joinContext.normalizedBase + this.pathSeparator + joinContext.normalizedRelative
        : joinContext.baseURL;
    }

    return requestedURL;
  }
}

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
export default function isAbsoluteURL(url) {
  return new PathAssembler().schemeRelativePattern.test(url);
}

